    private Button icon(String kind,String tip,Runnable action){if(englishChrome())tip=switch(kind){case"open"->"Open";case"save"->"Save";case"print"->"Print";case"pdf"->"PDF";case"first"->"First";case"prev"->previousButtonCount++==0?"Previous":"Previous result";case"next"->"Next";case"last"->"Last";case"minus"->"Zoom out";case"plus"->"Zoom in";case"png"->"PNG";case"svg"->"SVG";case"search"->"Search / next";case"cancel"->cancelButtonCount++==0?"Clear":"Cancel";case"help"->"Help";case"size"->"Icon size";case"close"->"Close";default->tip;};var b=new Button(tip);b.setContentDisplay(ContentDisplay.TOP);b.setStyle(BUTTON);b.setTooltip(new Tooltip(tip));b.setAccessibleText(tip);b.setUserData(kind);b.setGraphic(svg(kind));b.setOnAction(e->action.run());return b;}
    private static boolean englishChrome(){var requested=System.getProperty("reports.preview.language","");return requested.toLowerCase(java.util.Locale.ROOT).startsWith("en")||(requested.isBlank()&&java.util.Locale.getDefault().getLanguage().equals("en"));}
    private SVGPath svg(String kind){var p=new SVGPath();p.setContent(switch(kind){case"open"->"M1 5h6l2 2h6v8H1zM1 5V2h6l2 2";case"save"->"M2 1h11l2 2v12H2zM5 1v5h7V1M5 12h7";case"search"->"M7 1a6 6 0 100 12A6 6 0 007 1m4.5 10.5L15 15";case"help"->"M8 1a7 7 0 100 14A7 7 0 008 1M6 6a2 2 0 114 1c0 1-2 1-2 3M8 12v1";case"first"->"M3 2h2v12H3zM6 8l7-6v12z";case"prev"->"M12 2L4 8l8 6z";case"next"->"M4 2l8 6-8 6z";case"last"->"M11 2h2v12h-2zM10 8L3 2v12z";case"plus"->"M7 1h2v6h6v2H9v6H7V9H1V7h6z";case"minus"->"M1 7h14v2H1z";case"png"->"M2 1h9l3 3v11H2zM4 11l3-4 2 3 2-2 2 3z";case"svg"->"M2 1h9l3 3v11H2zM4 8l2-2-2-2M10 4l-2 2 2 2";case"pdf"->"M2 1h9l3 3v11H2zM4 12V8h2a2 2 0 010 4zM9 8v4h2";case"print"->"M4 1h8v4H4zM3 6h10a2 2 0 012 2v4h-3v3H4v-3H1V8a2 2 0 012-2z";case"cancel"->"M3 3l10 10M13 3L3 13";case"size"->"M1 1h6v6H1zM9 9h6v6H9zM10 1h5v5M1 10v5h5";case"close"->"M2 2l12 12M14 2L2 14";default->"M2 2h12v12H2z";});p.setStroke(Color.web("#0f172a"));p.setFill(kind.matches("first|prev|next|last|plus|minus")?Color.web("#0f172a"):Color.TRANSPARENT);p.setStrokeWidth(1.5);double scale=iconSize/16d;p.setScaleX(scale);p.setScaleY(scale);return p;}
    private void showPage(int value){page=Math.max(0,Math.min(sample.pageCount()-1,value));pageBox.setText(Integer.toString(page+1));count.setText("／ 全"+sample.pageCount()+"ページ");for(int i=0;i<thumbnails.getItems().size();i++)if(thumbnails.getItems().get(i).page()==page){thumbnails.getSelectionModel().select(i);break;}render();}
    private void goToInput(){try{showPage(Integer.parseInt(pageBox.getText().trim())-1);}catch(NumberFormatException ex){pageBox.setText(Integer.toString(page+1));}}
    private void render(){cancel();var generation=++operationGeneration;var token=new AtomicBoolean();activeCancellation=token;var snapshot=sample;progress.setProgress(ProgressIndicator.INDETERMINATE_PROGRESS);progress.setVisible(true);var requested=page;var activeHit=searchIndex>=0&&searchIndex<searchHits.size()?searchHits.get(searchIndex):null;var control=new RenderControl(token::get,v->Platform.runLater(()->{if(current(generation,snapshot))progress.setProgress(v);}));rendering=executor.submit(()->{try{var p=snapshot.pages().get(requested);int dpi=fixedPercent()*144/100;var buffered=pageRenderer.render(p,dpi,control);if(activeHit!=null&&activeHit.page()==requested)highlightSearchHit(buffered,activeHit,dpi);var fx=SwingFXUtils.toFXImage(buffered,null);Platform.runLater(()->{if(current(generation,snapshot)&&page==requested){image.setImage(fx);applyZoom();progress.setVisible(false);}});}catch(CancellationException ignored){Platform.runLater(()->{if(current(generation,snapshot))progress.setVisible(false);});}catch(Exception ex){Platform.runLater(()->{if(current(generation,snapshot)){progress.setVisible(false);error(ex);}});}});}
    private boolean current(long generation,SampleCatalog.Sample snapshot){return operationGeneration==generation&&sample==snapshot;}
    private void applyZoom(){if(image.getImage()==null)return;double viewportWidth=Math.max(1,previewScroll.getWidth()-18),viewportHeight=Math.max(1,previewScroll.getHeight()-18);double scale=zoomScale(zoomMode,image.getImage().getWidth(),image.getImage().getHeight(),viewportWidth,viewportHeight);image.setFitWidth(image.getImage().getWidth()*scale);image.setFitHeight(image.getImage().getHeight()*scale);}
    static double zoomScale(String mode,double imageWidth,double imageHeight,double viewportWidth,double viewportHeight){double availableWidth=Math.max(1,viewportWidth-58),availableHeight=Math.max(1,viewportHeight-58);return switch(mode){case"ページ幅"->Math.max(.05,availableWidth/imageWidth);case"ページ全体"->Math.max(.05,Math.min(availableWidth/imageWidth,availableHeight/imageHeight));case"実寸"->96d/144;default->{try{yield Math.max(.05,Integer.parseInt(mode.substring(0,mode.length()-1))/100d);}catch(Exception ex){yield 1;}}};}
    private int fixedPercent(){if(zoomMode!=null&&zoomMode.endsWith("%"))return Integer.parseInt(zoomMode.substring(0,zoomMode.length()-1));return 100;}
    private void stepZoom(int delta){int current=java.util.Arrays.asList(FIXED).indexOf(zoomMode);if(current<0)current=2;zoom.setValue(FIXED[Math.max(0,Math.min(FIXED.length-1,current+delta))]);}
    private void cancel(){operationGeneration++;activeCancellation.set(true);var printing=activePrint;if(printing!=null)printing.cancel();if(rendering!=null)rendering.cancel(true);if(printing!=null&&!printing.hasStarted()&&activePrint==printing){activePrint=null;restorePrintControls();}progress.setVisible(false);}
    private void restorePrintControls(){if(printDisabledRoot!=null){printDisabledRoot.setDisable(printPriorDisabled);printDisabledRoot=null;}}
    static int[] thumbnailRange(int page,int pageCount){int start=pageCount>200?Math.max(0,Math.min(page-100,pageCount-200)):0;return new int[]{start,Math.min(pageCount,start+200)};}
    private void loadThumbnails(){if(!thumbnails.isVisible())return;if(thumbnailRendering!=null)thumbnailRendering.cancel(true);var generation=++thumbnailGeneration;var snapshot=sample;thumbnails.getItems().clear();var range=thumbnailRange(page,snapshot.pageCount());int start=range[0],end=range[1];thumbnailRendering=executor.submit(()->{for(int i=start;i<end&&!Thread.currentThread().isInterrupted();i++){var p=snapshot.pages().get(i);var buffered=new ReportRenderer().renderPage(p.definition(),p.data(),new RenderOptions(36,false,p.sourcePage()),p.sourcePage(),RenderControl.none());var thumb=new Thumb(i,SwingFXUtils.toFXImage(buffered,null));Platform.runLater(()->{if(thumbnailGeneration==generation&&sample==snapshot)thumbnails.getItems().add(thumb);});}});}
    private File choose(String title,String extension){var chooser=new FileChooser();chooser.setInitialFileName(sample.name()+extension);chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter(title,"*"+extension));return chooser.showSaveDialog(stage);}
    private void savePng(){var file=choose("PNG",".png");if(file==null)return;try{var p=sample.pages().get(page);atomicWrite(file.toPath(),temporary->{var rendered=new ReportRenderer().renderPage(p.definition(),p.data(),RenderOptions.preview(),p.sourcePage(),RenderControl.none());try{if(!ImageIO.write(rendered,"png",temporary.toFile()))throw new IOException("PNG writer unavailable");}finally{rendered.flush();}});}catch(Exception ex){error(ex);}}
    private void saveSvg(){var file=choose("SVG",".svg");if(file==null)return;try{var p=sample.pages().get(page);atomicWrite(file.toPath(),temporary->Files.writeString(temporary,new SvgExporter().svg(p.definition(),p.data(),p.sourcePage())));}catch(Exception ex){error(ex);}}
    @FunctionalInterface interface AtomicFileWriter{void write(Path temporary)throws Exception;}
    static void atomicWrite(Path target,AtomicFileWriter writer)throws Exception{Path selected=target.toAbsolutePath().normalize(),parent=selected.getParent();if(parent==null||!Files.isDirectory(parent))throw new IOException("Output target must have an existing parent");Path destination=Files.isSymbolicLink(selected)?selected.toRealPath():parent.toRealPath().resolve(selected.getFileName());parent=destination.getParent();if(Files.exists(destination)&&(!Files.isRegularFile(destination)||!Files.isWritable(destination)))throw new IOException("Output target is not a writable regular file");Path temporary=Files.createTempFile(parent,".reports-preview-",".part");Throwable failure=null;try{SampleJobExporter.prepareOutputFile(destination,temporary,parent);writer.write(temporary);SampleJobExporter.finishOutputFile(destination,temporary);Files.move(temporary,destination,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(Exception|Error ex){failure=ex;throw ex;}finally{try{Files.deleteIfExists(temporary);}catch(IOException cleanup){if(failure!=null)failure.addSuppressed(cleanup);else throw cleanup;}}}
    private void savePdf(){var file=choose("PDF",".pdf");if(file==null)return;cancel();var generation=++operationGeneration;var token=new AtomicBoolean();activeCancellation=token;var snapshot=sample;progress.setProgress(0);progress.setVisible(true);var control=new RenderControl(token::get,v->Platform.runLater(()->{if(current(generation,snapshot))progress.setProgress(v);}));rendering=executor.submit(()->{try{SampleJobExporter.exportPdf(snapshot,file.toPath(),control);Platform.runLater(()->{if(current(generation,snapshot))progress.setVisible(false);});}catch(CancellationException ignored){Platform.runLater(()->{if(current(generation,snapshot))progress.setVisible(false);});}catch(Exception ex){Platform.runLater(()->{if(current(generation,snapshot)){progress.setVisible(false);error(ex);}});}});}
    private void print(){
        if(activePrint!=null)return;
        cancel();progress.setProgress(ProgressIndicator.INDETERMINATE_PROGRESS);progress.setVisible(true);
        final SamplePrintService service;
        try{service=SamplePrintService.create(sample);}catch(Exception ex){progress.setVisible(false);error(ex);return;}
        activePrint=service;
        printDisabledRoot=stage.getScene().getRoot();printPriorDisabled=printDisabledRoot.isDisable();printDisabledRoot.setDisable(true);
        rendering=executor.submit(()->{try{service.run();}
            catch(InterruptedException ex){Thread.currentThread().interrupt();service.cancel();}
            catch(Exception ex){Platform.runLater(()->{if(activePrint==service&&!service.isCancelled()&&stage.isShowing())error(ex);});}
            finally{Platform.runLater(()->{if(activePrint==service){activePrint=null;restorePrintControls();if(!service.isCancelled())progress.setVisible(false);}});}
        });
    }
